function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(10, 10, W - 20, H - 20);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Silence', 20, 20);
  ctx.fillText('Please', 20, 50);
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.rect(20 + i * 100, H - 50, 50, 30);
    ctx.stroke();
    ctx.fillStyle = 'black';
    ctx.font = '18px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Book', 20 + i * 100 + 25, H - 25);
    ctx.fillStyle = '#f5f0e8';
    ctx.fillRect(20 + i * 100 + 5, H - 45, 40, 20);
    ctx.fillStyle = 'black';
    ctx.font = '18px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(Math.floor(Math.sin(t + i) * 10), 20 + i * 100 + 25, H - 25);
  }
  ctx.restore();
}
